const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binaryObj = item.binary || {};
  const binaryKey = Object.keys(binaryObj)[0] || 'data';

  let base64Data = '';
  let mimeType = 'image/png';

  if (binaryObj[binaryKey]) {
    mimeType = binaryObj[binaryKey].mimeType || 'image/png';
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(i, binaryKey);
      base64Data = buffer.toString('base64');
    } catch (e) {
      if (typeof binaryObj[binaryKey].data === 'string' && binaryObj[binaryKey].data.length > 50) {
        base64Data = binaryObj[binaryKey].data;
      }
    }
  }

  const slipId = item.json.body?.slip_id || item.json.slip_id || 'ce149694-3228-4951-897a-5be5ed52f55c';

  results.push({
    json: {
      slip_id: slipId,
      mime_type: mimeType,
      image_url: `data:${mimeType};base64,${base64Data}`
    }
  });
}

return results;

