const item = $input.first();
const content = item.json.choices?.[0]?.message?.content || '{}';
const slipId = $('Prepare Image Payload').first().json.slip_id || 'ce149694-3228-4951-897a-5be5ed52f55c';

let parsed = {};
try {
  const cleanContent = content.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanContent);
} catch (e) {
  parsed = { raw_output: content, error: 'JSON parse error' };
}

return [{
  json: {
    slip_id: slipId,
    parsed_data: parsed,
    status: 'Parsed'
  }
}];
